<?php
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function savePage($path,$content){if(!is_dir(dirname($path)))mkdir(dirname($path),0755,true);need(file_put_contents($path,$content)!==false,'Failed writing page');}
function shellPage($title,$content,$active='home',$description='每天一站，看懂 AI 新进展。国内外热点、GitHub 开源周榜，附详细中文解读与原文链接。',$path='/'){
 $nav=array('home'=>array('/','今日发现'),'news'=>array('/news/','AI 热点'),'repos'=>array('/repos/','开源周榜'),'archive'=>array('/archive/','往期归档'));
 $links='';foreach($nav as $key=>$v)$links.='<a '.($active===$key?'aria-current="page"':'').' href="'.$v[0].'">'.$v[1].'</a>';
 return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="'.h($description).'"><meta name="theme-color" content="#f5f4ee"><title>'.h($title).' · 启步 AI</title><link rel="canonical" href="https://xmqibu.com'.h($path).'"><meta property="og:title" content="'.h($title).'"><meta property="og:description" content="'.h($description).'"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">跳到正文</a><header class="top"><a class="brand" href="/" aria-label="启步 AI 首页"><span class="mark">↗</span><b>启步<span> AI</span></b></a><nav aria-label="主导航">'.$links.'</nav><span class="edition">THE DAILY SIGNAL <i></i></span></header><main id="main">'.$content.'</main><footer><div><a class="brand" href="/">启步 AI <span>↗</span></a><p>发现值得关注的技术，理解变化背后的价值。</p></div><div><a href="/about/">关于本站与榜单规则</a><p>AI 辅助整理 · 事实以原始来源为准</p><a href="https://beian.miit.gov.cn/" target="_blank" rel="noopener noreferrer">闽ICP备2022008558号-1</a></div></footer></body></html>';
}
function card($i,$rank=null){$repo=$i['kind']==='repo';$meta=$repo?'GITHUB / '.h(isset($i['language'])?$i['language']:'OPEN SOURCE'):h($i['region']).' / '.h($i['source']);$stats=$repo?'<span class="growth">↗ +'.number_format($i['weeklyStars']).'<small>近 7 天 Star</small></span>':'<span class="date">'.h($i['editionDate']).'</span>';
 return '<article class="story" data-category="'.h($i['category']).'" data-region="'.h($i['region']).'" data-search="'.h($i['title'].' '.$i['intro'].' '.$i['category']).'"><div class="story-meta"><span>'.$meta.'</span>'.($rank!==null?'<span class="rank">'.sprintf('%02d',$rank).'</span>':'').'</div><span class="tag">'.h($i['category']).'</span><h3><a href="/read/'.$i['id'].'/">'.h($i['title']).'</a></h3><p>'.h($i['intro']).'</p><div class="story-bottom">'.$stats.'<a class="read" href="/read/'.$i['id'].'/">详细介绍 ↗</a></div><a class="source-link" href="'.h($i['url']).'" target="_blank" rel="noopener noreferrer">'.($repo?'查看 GitHub 项目':'阅读原文').' ↗</a></article>';
}
function filters($items,$regions=true){$cats=array_values(array_unique(array_column($items,'category')));$out='<div class="filters"><label class="search"><span>⌕</span><input type="search" id="search" placeholder="搜索标题、项目或关键词" aria-label="搜索资讯"></label><label class="select-label">分类<select id="category"><option value="">全部分类</option>';foreach($cats as $c)$out.='<option>'.h($c).'</option>';$out.='</select></label>';if($regions)$out.='<label class="select-label">地区<select id="region"><option value="">全部地区</option><option>国内</option><option>海外</option></select></label>';return $out.'</div><p class="filter-count" aria-live="polite"></p>';
}
function renderSite($items,$editions,$out){
 $latest=$editions[0]['edition_date'];$latestItems=array_values(array_filter($items,function($i)use($latest){return $i['editionDate']===$latest;}));
 $news=array_values(array_filter($latestItems,function($i){return $i['kind']==='news';}));$repos=array_values(array_filter($latestItems,function($i){return $i['kind']==='repo';}));
 usort($repos,function($a,$b){return $b['weeklyStars']<=>$a['weeklyStars'];});usort($news,function($a,$b){return $b['score']<=>$a['score'];});
 $updated=(new DateTimeImmutable($editions[0]['collected_at']))->setTimezone(new DateTimeZone('Asia/Shanghai'))->format('Y.m.d H:i');
 $hero='<section class="hero"><div><div class="eyebrow"><span class="live-dot"></span> 独立视角 · 每日更新</div><h1>跟上 AI 的变化。<br><em>找到你的下一步。</em></h1><p>从全球热点到快速成长的开源项目，<br>把值得关注的进展，整理成读得懂的中文。</p><div class="hero-actions"><a class="button" href="/news/">阅读本期热点 <span>↗</span></a><a href="/repos/">探索开源周榜 ↗</a></div></div><div class="signal-panel"><div class="signal-top"><span>SIGNAL / '.h(str_replace('-','.',$latest)).'</span><span>✳</span></div><div class="signal-title">今天，<br>从这里开始<span>↗</span></div><div class="signal-stats"><div><b>'.count($news).'</b><span>精选资讯</span></div><div><b>'.count($repos).'</b><span>开源项目</span></div></div><div class="signal-foot">每日 12:00 采集 · 北京时间</div></div></section><div class="update-bar"><span>本期更新 <strong>'.h($updated).'</strong></span><span>原始来源可追溯 <i>✳</i> 技术变化有据可循</span></div>';
 $home=$hero.'<section class="section"><div class="section-head"><div><span class="eyebrow">01 / THE AI BRIEF</span><h2>AI 热点<span>值得知道，值得思考。</span></h2></div><a href="/news/">全部资讯 ↗</a></div><div class="cards">';foreach(array_slice($news,0,6) as $i)$home.=card($i);if(!$news)$home.='<div class="empty">本期尚无通过来源与日期核验的新闻。<a href="/archive/">查看往期内容 ↗</a></div>';$home.='</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">02 / OPEN SOURCE RADAR</span><h2>开源周榜<span>看看开发者正在关注什么。</span></h2></div><a href="/repos/">完整榜单 ↗</a></div><p class="method">按已采集 GitHub 周趋势项目的近 7 天 Star 增量排序，非全站穷举排名。</p><div class="cards repos">';foreach(array_slice($repos,0,6) as $n=>$i)$home.=card($i,$n+1);$home.='</div></section>';savePage($out.'/index.html',shellPage('发现 AI 的下一步',$home));
 foreach(array('news'=>$news,'repos'=>$repos) as $kind=>$list){$title=$kind==='news'?'每日 AI 热点':'GitHub 开源周榜';$desc=$kind==='news'?'国内外 AI 新动态，附详细介绍与原始报道。':'近 7 天 Star 增长，寻找值得深入了解的开源项目。';$body='<section class="page-heading"><span class="eyebrow">'.($kind==='news'?'THE AI BRIEF':'OPEN SOURCE RADAR').'</span><h1>'.$title.'</h1><p>'.$desc.'</p><p class="method">本期 '.h($latest).' · '.($kind==='news'?'按报道来源覆盖与时效排序，不代表全网阅读量。':'覆盖 GitHub 全站及 Python、TypeScript、Rust、Go 周趋势候选，按已采集增量排序。').'</p></section>'.filters($list,$kind==='news').'<div class="cards filter-items">';foreach($list as $n=>$i)$body.=card($i,$kind==='repos'?$n+1:null);$body.='</div><p class="empty no-results" hidden>没有匹配内容，试试其他关键词或分类。</p>';savePage($out.'/'.$kind.'/index.html',shellPage($title,$body,$kind,$desc,'/'.$kind.'/'));}
 foreach($items as $i){$body='<div class="article-layout"><article class="article"><a class="back" href="/'.($i['kind']==='repo'?'repos':'news').'/">← 返回'.($i['kind']==='repo'?'开源周榜':'AI 热点').'</a><div class="eyebrow">'.h($i['category']).' / '.h($i['region']).'</div><h1>'.h($i['title']).'</h1><div class="article-meta">'.h($i['source']).' · '.h($i['editionDate']).' · AI 辅助整理</div><p class="lead">'.h($i['intro']).'</p>';
 if($i['kind']==='repo')$body.='<div class="repo-metrics"><div><b>+'.number_format($i['weeklyStars']).'</b>近 7 天 Star</div><div><b>'.number_format($i['totalStars']).'</b>总 Star</div></div>';
 foreach($i['sections'] as $s)$body.='<section><h2>'.h($s['heading']).'</h2><p>'.nl2br(h($s['text'])).'</p></section>';
 $body.='<a class="button" href="'.h($i['url']).'" target="_blank" rel="noopener noreferrer">'.($i['kind']==='repo'?'前往 GitHub 查看项目':'阅读完整原文').' ↗</a></article><aside class="article-aside"><span class="eyebrow">SOURCE NOTES</span><h3>从原始信息出发</h3><p>本文为中文整理与解读，功能、数据和使用条件以原文为准。</p><ul>';foreach($i['evidence'] as $e)$body.='<li><a href="'.h($e['url']).'" target="_blank" rel="noopener noreferrer">'.h($e['name']).' ↗</a></li>';
 if($i['kind']==='repo')$body.='<li><a href="'.h($i['rankingSource']).'" target="_blank" rel="noopener noreferrer">GitHub 周趋势数据 ↗</a></li>';
 $body.='</ul><p>'.($i['kind']==='news'?'原文时间：'.h((new DateTimeImmutable($i['publishedAt']))->setTimezone(new DateTimeZone('Asia/Shanghai'))->format('Y-m-d H:i')).' 北京时间':'Star 增量为采集时 GitHub 周趋势展示值。').'</p></aside></div>';savePage($out.'/read/'.$i['id'].'/index.html',shellPage($i['title'],$body,$i['kind']==='repo'?'repos':'news',$i['intro'],'/read/'.$i['id'].'/'));}
 $archive='<section class="page-heading"><span class="eyebrow">THE ARCHIVE</span><h1>每一步，都有迹可循。</h1><p>按日期回看 AI 热点与开源项目。</p></section><div class="archive-list">';foreach($editions as $ed){$d=$ed['edition_date'];$day=array_values(array_filter($items,function($i)use($d){return $i['editionDate']===$d;}));$archive.='<a href="/archive/'.$d.'/"><b>'.h($d).'</b><span>'.count($day).' 条内容 ↗</span></a>';$html='<section class="page-heading"><span class="eyebrow">PAST EDITION</span><h1>'.h($d).'</h1><p>本期资讯与项目快照</p></section><div class="cards">';foreach($day as $i)$html.=card($i);savePage($out.'/archive/'.$d.'/index.html',shellPage($d.' 归档',$html.'</div>','archive','当日资讯与项目快照','/archive/'.$d.'/'));}savePage($out.'/archive/index.html',shellPage('往期归档',$archive.'</div>','archive','','/archive/'));
 $about='<article class="article about"><span class="eyebrow">ABOUT QIBU AI</span><h1>让技术信息，更有价值。</h1><p class="lead">启步 AI 面向 AI 爱好者和开发者，每日整理国内外 AI 进展及快速成长的开源项目。</p><h2>内容与更新</h2><p>每天北京时间 12:00 开始采集，完成核验后更新。新闻仅收录以 AI 为核心、原始发布时间属于该北京自然日的内容；已发布事件及同一事件的转载不重复收录；原文不可读或事实不足时跳过，不用旧新闻补数量。运行失败时保留上次成功内容，页面明确显示实际采集日期。</p><h2>开源榜单范围</h2><p>采集 GitHub 全站及 Python、TypeScript、Rust、Go 周趋势候选，去重后按 GitHub 展示的 stars this week 降序排列。这是已采集候选范围的近 7 天增长榜，并非 GitHub 全站所有项目的严格排名；总 Star 与周增量分别展示。周榜包含 AI 及其他有价值的开源项目。已经推荐过的项目不再跨天重复推荐，因此本期展示的是去重后的新增项目。</p><h2>新闻热度如何判断</h2><p>按可验证的独立报道域名数量和时效排序：每个独立域名20分（最多100分），时效最多10分；不是阅读量、转发量或全网热搜排名。单一来源也可能收录，但不会虚构其他报道。地区按事件主要发生地分类，跨地区事件由编辑判断。</p><h2>阅读与来源</h2><p>介绍由 AI 辅助整理，保留来源链接，区分已知事实和使用场景解读。请以原文、官方文档及项目许可为准。本站不转载原文全文，也不提供新闻来源中软件的安全保证。</p><h2>纠错</h2><p>发现错误时，请通过原文核对，或联系本站维护者提供文章地址和证据。更正后会重新发布当前版本。</p></article>';savePage($out.'/about/index.html',shellPage('关于本站与榜单规则',$about,'','','/about/'));
 savePage($out.'/404.html',shellPage('页面未找到','<section class="page-heading"><span class="eyebrow">404</span><h1>这一页，暂时走丢了。</h1><a class="button" href="/">返回首页 ↗</a></section>'));
 foreach(array('style.css','app.js') as $asset)need(copy(__DIR__.'/../public/'.$asset,$out.'/'.$asset),'Copy failed');
 savePage($out.'/robots.txt',"User-agent: *\nAllow: /\nSitemap: https://xmqibu.com/sitemap.xml\n");$xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach(array('/','/news/','/repos/','/archive/','/about/') as $u)$xml.='<url><loc>https://xmqibu.com'.$u.'</loc></url>';foreach($items as $i)$xml.='<url><loc>https://xmqibu.com/read/'.$i['id'].'/</loc></url>';savePage($out.'/sitemap.xml',$xml.'</urlset>');
 savePage($out.'/health.json',json_encode(array('edition'=>$latest,'collectedAt'=>$editions[0]['collected_at'],'news'=>count($news),'repos'=>count($repos)),JSON_UNESCAPED_UNICODE));
}
